expansions.body:
umask 077
d='/var/backups/db1'
f='/var/backups/db1'/'shop'-'rel-1.5'-d7261f5c.dump
test -d "$d" || { echo "vpscfg: dest_dir does not exist" >&2; exit 2; }
if test -n "$(find "$d" -maxdepth 0 \( -perm -0002 -o -perm -1000 \) -print)"; then echo "vpscfg: dest_dir is world-writable or sticky; refused" >&2; exit 2; fi
if test -e "$f"; then echo "vpscfg: $f already exists; a dump is never overwritten" >&2; exit 3; fi
t=$(mktemp "$d/.vpscfg-dump.XXXXXX") || exit 4
r=$(mktemp "$d/.vpscfg-dump.XXXXXX") || { rm -f "$t"; exit 4; }
trap 'rm -f "$t" "$r"' EXIT
docker exec -e PGDATABASE='shop' 'pg-main' sh -c 'if [ -n "${POSTGRES_PASSWORD_FILE:-}" ] && [ -r "$POSTGRES_PASSWORD_FILE" ]; then PGPASSWORD=$(cat "$POSTGRES_PASSWORD_FILE"); else PGPASSWORD="${POSTGRES_PASSWORD:-${POSTGRESQL_PASSWORD:-}}"; fi; export PGPASSWORD; exec pg_dump -Fc --no-password -U "${POSTGRES_USER:-${POSTGRESQL_USERNAME:-postgres}}"' > "$t" || { echo "vpscfg: pg_dump failed" >&2; exit 4; }
test -s "$t" || { echo "vpscfg: the dump is empty" >&2; exit 5; }
docker exec -i 'pg-main' pg_restore --list < "$t" > /dev/null || { echo "vpscfg: pg_restore --list cannot read the dump" >&2; exit 6; }
h=$(sha256sum < "$t" | cut -d " " -f 1)
test -n "$h" || { echo "vpscfg: sha256sum failed" >&2; exit 7; }
printf '%s  %s\n' "$h" "$f" > "$r"
chmod 0600 "$t" "$r"
mv "$r" "$f.sha256" && mv "$t" "$f" || exit 8
echo "vpscfg: dumped $(wc -c < "$f" | tr -d " ") bytes to $f, sha256 $h"

